/* ============================================================
   今天吃啥 AI 版 · 菜友圈（吃货朋友圈）
   ============================================================ */
(function () {
  "use strict";
  const $ = (sel) => document.querySelector(sel);
  const $$ = (sel, ctx) => Array.from((ctx || document).querySelectorAll(sel));

  const LS_MOMENTS = "eat-ai-moments";
  const LS_MOMENTS_LIKES = "eat-ai-moments-likes";

  // 模拟用户数据
  const MOCK_USERS = [
    { name: "吃货小王", avatar: "🍳" },
    { name: "美食家小李", avatar: "🍜" },
    { name: "厨房新手", avatar: "🥘" },
    { name: "健康饮食达人", avatar: "🥗" },
    { name: "川菜爱好者", avatar: "🌶️" },
    { name: "甜品控", avatar: "🍰" },
    { name: "深夜食堂", avatar: "🍱" },
    { name: "素食主义", avatar: "🥬" },
  ];

  // 模拟动态数据
  const MOCK_MOMENTS = [
    {
      id: "m1",
      user: MOCK_USERS[0],
      text: "今天做了番茄牛腩，炖了两个小时，入口即化！配米饭绝了🍚",
      dish: "番茄牛腩",
      images: ["🍅", "🥩", "🍚"],
      likes: ["美食家小李", "厨房新手"],
      comments: [
        { user: "美食家小李", text: "看着就好吃！求教程" },
        { user: "厨房新手", text: "番茄要炒出沙吗？" },
      ],
      ts: Date.now() - 3600000,
    },
    {
      id: "m2",
      user: MOCK_USERS[1],
      text: "周末和朋友一起做了满汉全席，从下午忙到晚上，累并快乐着！",
      dish: "家庭聚餐",
      images: ["🦐", "🐟", "🍗", "🥬", "🍲", "🍚"],
      likes: ["吃货小王", "健康饮食达人", "川菜爱好者"],
      comments: [
        { user: "吃货小王", text: "太丰盛了吧！" },
      ],
      ts: Date.now() - 7200000,
    },
    {
      id: "m3",
      user: MOCK_USERS[2],
      text: "第一次做可乐鸡翅，虽然有点糊了，但是味道还不错！继续加油💪",
      dish: "可乐鸡翅",
      images: ["🍗"],
      likes: ["甜品控"],
      comments: [],
      ts: Date.now() - 10800000,
    },
    {
      id: "m4",
      user: MOCK_USERS[3],
      text: "今日健康餐：鸡胸肉沙拉 + 藜麦饭，低卡高蛋白，减脂期必备！",
      dish: "鸡胸肉沙拉",
      images: ["🥗", "🍚"],
      likes: ["素食主义", "深夜食堂"],
      comments: [
        { user: "素食主义", text: "可以把鸡胸肉换成豆腐哦" },
      ],
      ts: Date.now() - 14400000,
    },
    {
      id: "m5",
      user: MOCK_USERS[4],
      text: "麻婆豆腐+水煮鱼，辣得过瘾！四川人的快乐就是这么简单🌶️",
      dish: "麻婆豆腐",
      images: ["🌶️", "🐟", "🍚"],
      likes: ["吃货小王", "美食家小李"],
      comments: [
        { user: "美食家小李", text: "看着就流口水了" },
        { user: "甜品控", text: "太辣了不敢吃😂" },
      ],
      ts: Date.now() - 18000000,
    },
  ];

  // 加载动态数据
  function loadMoments() {
    try {
      const saved = JSON.parse(localStorage.getItem(LS_MOMENTS) || "null");
      if (saved && saved.length) return saved;
    } catch (e) {}
    // 首次使用，保存模拟数据
    localStorage.setItem(LS_MOMENTS, JSON.stringify(MOCK_MOMENTS));
    return MOCK_MOMENTS;
  }

  function saveMoments(moments) {
    localStorage.setItem(LS_MOMENTS, JSON.stringify(moments.slice(0, 50)));
  }

  // 加载点赞状态
  function loadLikes() {
    try { return JSON.parse(localStorage.getItem(LS_MOMENTS_LIKES) || "{}"); }
    catch (e) { return {}; }
  }

  function saveLikes(likes) {
    localStorage.setItem(LS_MOMENTS_LIKES, JSON.stringify(likes));
  }

  // 格式化时间
  function formatTime(ts) {
    const diff = Date.now() - ts;
    const min = Math.floor(diff / 60000);
    if (min < 1) return "刚刚";
    if (min < 60) return min + "分钟前";
    const hour = Math.floor(min / 60);
    if (hour < 24) return hour + "小时前";
    const day = Math.floor(hour / 24);
    if (day < 7) return day + "天前";
    const d = new Date(ts);
    return (d.getMonth() + 1) + "月" + d.getDate() + "日";
  }

  // 渲染动态列表
  function renderMoments() {
    const moments = loadMoments();
    const likes = loadLikes();
    const listEl = $("#momentsList");
    if (!listEl) return;

    listEl.innerHTML = moments.map(m => {
      const isLiked = likes[m.id];
      const likeCount = m.likes.length + (isLiked ? 1 : 0);
      const imagesHTML = m.images && m.images.length
        ? `<div class="moment-images">${m.images.slice(0, 9).map(img => `<div class="moment-img">${img}</div>`).join("")}</div>`
        : "";
      const dishHTML = m.dish ? `<span class="moment-dish-tag">🍽️ ${m.dish}</span>` : "";
      const likesHTML = likeCount > 0
        ? `<div class="moment-likes">❤️ ${m.likes.join("、")}${isLiked ? "、我" : ""} 等${likeCount}人觉得很赞</div>`
        : "";
      const commentsHTML = m.comments && m.comments.length
        ? `<div class="moment-comments">${m.comments.map(c => `<div class="moment-comment"><b>${c.user}</b>：${c.text}</div>`).join("")}</div>`
        : "";

      return `
        <div class="moment-item" data-id="${m.id}">
          <div class="moment-avatar">${m.user.avatar}</div>
          <div class="moment-body">
            <div class="moment-name">${m.user.name}</div>
            <div class="moment-text">${m.text}</div>
            ${dishHTML}
            ${imagesHTML}
            <div class="moment-footer">
              <span class="moment-time">${formatTime(m.ts)}</span>
              <div class="moment-actions">
                <button class="moment-action-btn btn-like ${isLiked ? "liked" : ""}" data-id="${m.id}">
                  ${isLiked ? "❤️" : "🤍"} ${likeCount || ""}
                </button>
                <button class="moment-action-btn btn-comment" data-id="${m.id}">
                  💬 ${m.comments.length || ""}
                </button>
              </div>
            </div>
            ${likesHTML}
            ${commentsHTML}
            <div class="moment-comment-input hidden" data-id="${m.id}">
              <input type="text" placeholder="说点什么..." class="comment-input">
              <button class="comment-submit">发送</button>
            </div>
          </div>
        </div>`;
    }).join("");

    // 绑定点赞事件
    $$(".btn-like", listEl).forEach(btn => {
      btn.addEventListener("click", () => {
        const id = btn.dataset.id;
        const likes = loadLikes();
        likes[id] = !likes[id];
        saveLikes(likes);
        renderMoments();
      });
    });

    // 绑定评论按钮事件
    $$(".btn-comment", listEl).forEach(btn => {
      btn.addEventListener("click", () => {
        const id = btn.dataset.id;
        const inputEl = $(`.moment-comment-input[data-id="${id}"]`);
        if (inputEl) {
          inputEl.classList.toggle("hidden");
          if (!inputEl.classList.contains("hidden")) {
            inputEl.querySelector("input").focus();
          }
        }
      });
    });

    // 绑定评论提交事件
    $$(".comment-submit", listEl).forEach(btn => {
      btn.addEventListener("click", () => {
        const inputWrap = btn.closest(".moment-comment-input");
        const id = inputWrap.dataset.id;
        const input = inputWrap.querySelector("input");
        const text = input.value.trim();
        if (!text) return;

        const moments = loadMoments();
        const m = moments.find(x => x.id === id);
        if (m) {
          m.comments.push({ user: "我", text });
          saveMoments(moments);
          renderMoments();
        }
      });
    });
  }

  // 发布动态
  function postMoment(text, dish) {
    const moments = loadMoments();
    const user = loadUser() || { name: "吃货", avatar: "🍅" };
    const newMoment = {
      id: "m" + Date.now(),
      user: { name: user.nickname || "吃货", avatar: user.avatar || "🍅" },
      text,
      dish: dish || "",
      images: [],
      likes: [],
      comments: [],
      ts: Date.now(),
    };
    moments.unshift(newMoment);
    saveMoments(moments);
    renderMoments();
  }

  function loadUser() {
    try { return JSON.parse(localStorage.getItem("eat-ai-user") || "null"); }
    catch (e) { return null; }
  }

  // 初始化
  function init() {
    // 渲染菜友圈
    renderMoments();

    // 更新用户信息
    const user = loadUser();
    const avatarEl = $("#momentsAvatar");
    const nameEl = $("#momentsName");
    if (avatarEl) avatarEl.textContent = user && user.avatar ? user.avatar : "🍅";
    if (nameEl) nameEl.textContent = user && user.nickname ? user.nickname : "吃货";

    // 发布动态按钮
    const postBtn = $("#btnMomentsPost");
    if (postBtn) {
      postBtn.addEventListener("click", () => {
        $("#momentsPostModal").classList.remove("hidden");
        $("#momentsPostText").value = "";
        $("#momentsPostDishName").textContent = "未关联";
      });
    }

    // 取消发布
    const cancelBtn = $("#btnMomentsPostCancel");
    if (cancelBtn) {
      cancelBtn.addEventListener("click", () => {
        $("#momentsPostModal").classList.add("hidden");
      });
    }

    // 提交发布
    const submitBtn = $("#btnMomentsPostSubmit");
    if (submitBtn) {
      submitBtn.addEventListener("click", () => {
        const text = $("#momentsPostText").value.trim();
        const dish = $("#momentsPostDishName").textContent;
        if (!text) { alert("说点什么吧~"); return; }
        postMoment(text, dish === "未关联" ? "" : dish);
        $("#momentsPostModal").classList.add("hidden");
        if (window.toast) window.toast("发布成功！");
      });
    }

    // 点击弹层背景关闭
    const modal = $("#momentsPostModal");
    if (modal) {
      modal.addEventListener("click", (e) => {
        if (e.target === modal) modal.classList.add("hidden");
      });
    }

    // 选择关联菜品（简单实现，随机选一个）
    const pickDishBtn = $("#btnMomentsPickDish");
    if (pickDishBtn) {
      pickDishBtn.addEventListener("click", () => {
        const dishes = ["番茄炒蛋", "红烧肉", "可乐鸡翅", "麻婆豆腐", "清蒸鲈鱼", "宫保鸡丁", "糖醋里脊", "蒜蓉西兰花"];
        const dish = dishes[Math.floor(Math.random() * dishes.length)];
        $("#momentsPostDishName").textContent = dish;
      });
    }
  }

  // 暴露给全局
  window.renderMoments = renderMoments;
  window.momentsInit = init;

  // DOM加载完成后初始化
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }
})();


/* ===== js\social.js ===== */
/* ============================================================
 * 今天吃啥AI版 - 社交功能（通讯录/个人资料/聊天/好友关系）
 * ============================================================ */

(function () {
  "use strict";

  // ========== 模拟用户数据 ==========
  const MOCK_USERS = [
    { id: "u001", name: "吃货小王", avatar: "🍔", signature: "人生苦短，必须吃饱", location: "上海", dishes: ["红烧肉", "麻婆豆腐"], isFriend: true },
    { id: "u002", name: "美食家小李", avatar: "🍜", signature: "吃遍天下美食", location: "北京", dishes: ["北京烤鸭", "炸酱面"], isFriend: true },
    { id: "u003", name: "厨房小白", avatar: "🥗", signature: "正在学做饭", location: "广州", dishes: ["白切鸡", "煲仔饭"], isFriend: true },
    { id: "u004", name: "辣妹子", avatar: "🌶️", signature: "无辣不欢", location: "成都", dishes: ["火锅", "水煮鱼"], isFriend: false },
    { id: "u005", name: "甜品控", avatar: "🍰", signature: "甜品是另一个胃", location: "杭州", dishes: ["西湖醋鱼", "龙井虾仁"], isFriend: false },
    { id: "u006", name: "健身达人", avatar: "💪", signature: "吃健康的，练最狠的", location: "深圳", dishes: ["鸡胸肉沙拉", "糙米饭"], isFriend: false },
    { id: "u007", name: "夜宵王者", avatar: "🍢", signature: "深夜放毒", location: "长沙", dishes: ["小龙虾", "臭豆腐"], isFriend: false },
    { id: "u008", name: "素食主义", avatar: "🥦", signature: "吃素也能很美味", location: "南京", dishes: ["素什锦", "豆腐煲"], isFriend: false }
  ];

  // ========== localStorage keys ==========
  const LS_FRIENDS = "eat-ai-friends";
  const LS_CHAT_PREFIX = "eat-ai-chat-";
  const LS_FRIEND_REQUESTS = "eat-ai-friend-requests";

  // ========== 当前查看的用户 ==========
  let currentProfileUser = null;
  let currentChatUser = null;

  // ========== 工具函数 ==========
  function $(sel) { return document.querySelector(sel); }
  function $$(sel) { return Array.from(document.querySelectorAll(sel)); }

  function getFriends() {
    try {
      const data = localStorage.getItem(LS_FRIENDS);
      if (data) return JSON.parse(data);
    } catch (e) {}
    // 默认好友
    return MOCK_USERS.filter(u => u.isFriend).map(u => u.id);
  }

  function saveFriends(friends) {
    localStorage.setItem(LS_FRIENDS, JSON.stringify(friends));
  }

  function isFriend(userId) {
    return getFriends().includes(userId);
  }

  function addFriend(userId) {
    const friends = getFriends();
    if (!friends.includes(userId)) {
      friends.push(userId);
      saveFriends(friends);
    }
  }

  function getUserById(userId) {
    return MOCK_USERS.find(u => u.id === userId);
  }

  function getChatMessages(userId) {
    try {
      const data = localStorage.getItem(LS_CHAT_PREFIX + userId);
      if (data) return JSON.parse(data);
    } catch (e) {}
    // 默认消息
    const user = getUserById(userId);
    if (user) {
      return [
        { from: userId, text: "你好呀！我是" + user.name + "，很高兴认识你！", time: Date.now() - 3600000 },
        { from: userId, text: "你平时喜欢吃什么呀？", time: Date.now() - 3500000 }
      ];
    }
    return [];
  }

  function saveChatMessages(userId, messages) {
    localStorage.setItem(LS_CHAT_PREFIX + userId, JSON.stringify(messages));
  }

  function formatTime(ts) {
    const d = new Date(ts);
    const now = new Date();
    if (d.toDateString() === now.toDateString()) {
      return d.getHours().toString().padStart(2, "0") + ":" + d.getMinutes().toString().padStart(2, "0");
    }
    return (d.getMonth() + 1) + "/" + d.getDate() + " " + d.getHours().toString().padStart(2, "0") + ":" + d.getMinutes().toString().padStart(2, "0");
  }

  // ========== 通讯录页面渲染 ==========
  function renderContacts() {
    const list = $("#contactsList");
    if (!list) return;

    const searchInput = $("#contactsSearchInput");
    const keyword = searchInput ? searchInput.value.trim().toLowerCase() : "";

    const friends = getFriends();
    let friendUsers = MOCK_USERS.filter(u => friends.includes(u.id));

    if (keyword) {
      friendUsers = friendUsers.filter(u =>
        u.name.toLowerCase().includes(keyword) ||
        u.signature.toLowerCase().includes(keyword)
      );
    }

    if (friendUsers.length === 0) {
      list.innerHTML = '<div class="contacts-empty">还没有菜友，点击下方按钮添加吧～</div>';
      return;
    }

    list.innerHTML = friendUsers.map(u => `
      <div class="contact-item" data-user-id="${u.id}">
        <div class="contact-avatar">${u.avatar}</div>
        <div class="contact-info">
          <div class="contact-name">${u.name}</div>
          <div class="contact-signature">${u.signature}</div>
        </div>
        <div class="contact-arrow">›</div>
      </div>
    `).join("");

    // 绑定点击事件
    $$(".contact-item").forEach(item => {
      item.addEventListener("click", () => {
        const userId = item.dataset.userId;
        showUserProfile(userId);
      });
    });
  }

  // ========== 显示用户个人资料 ==========
  function showUserProfile(userId) {
    const user = getUserById(userId);
    if (!user) return;

    currentProfileUser = user;

    const card = $("#profileCard");
    const actions = $("#profileActions");
    if (!card || !actions) return;

    const friend = isFriend(userId);

    card.innerHTML = `
      <div class="profile-header">
        <div class="profile-avatar">${user.avatar}</div>
        <div class="profile-info">
          <div class="profile-name">${user.name}</div>
          <div class="profile-location">📍 ${user.location}</div>
          <div class="profile-signature">${user.signature}</div>
        </div>
      </div>
      <div class="profile-dishes">
        <div class="profile-dishes-title">拿手菜</div>
        <div class="profile-dishes-list">
          ${user.dishes.map(d => `<span class="profile-dish-tag">${d}</span>`).join("")}
        </div>
      </div>
      <div class="profile-stats">
        <div class="profile-stat">
          <div class="profile-stat-num">${Math.floor(Math.random() * 50) + 10}</div>
          <div class="profile-stat-label">动态</div>
        </div>
        <div class="profile-stat">
          <div class="profile-stat-num">${getFriends().length || 0}</div>
          <div class="profile-stat-label">菜友</div>
        </div>
        <div class="profile-stat">
          <div class="profile-stat-num">${Math.floor(Math.random() * 100) + 20}</div>
          <div class="profile-stat-label">获赞</div>
        </div>
      </div>
    `;

    if (friend) {
      actions.innerHTML = `
        <button class="profile-action-btn primary" id="profileSendMsgBtn">💬 发消息</button>
      `;
      $("#profileSendMsgBtn").addEventListener("click", () => {
        startChat(userId);
      });
    } else {
      actions.innerHTML = `
        <button class="profile-action-btn primary" id="profileAddFriendBtn">➕ 加菜友</button>
      `;
      $("#profileAddFriendBtn").addEventListener("click", () => {
        addFriend(userId);
        alert("已添加" + user.name + "为菜友！");
        showUserProfile(userId); // 刷新
      });
    }

    if (window.showView) window.showView("user-profile");
  }

  // ========== 开始聊天 ==========
  function startChat(userId) {
    const user = getUserById(userId);
    if (!user) return;

    currentChatUser = user;

    const title = $("#chatTitle");
    if (title) title.textContent = user.name;

    renderChatMessages();

    if (window.showView) window.showView("chat");
  }

  // ========== 渲染聊天消息 ==========
  function renderChatMessages() {
    const container = $("#chatMessages");
    if (!container || !currentChatUser) return;

    const messages = getChatMessages(currentChatUser.id);
    const currentUser = getCurrentUser();

    container.innerHTML = messages.map(msg => {
      const isMe = msg.from === "me";
      return `
        <div class="chat-msg ${isMe ? "mine" : "other"}">
          ${!isMe ? `<div class="chat-msg-avatar">${currentChatUser.avatar}</div>` : ""}
          <div class="chat-msg-bubble">
            <div class="chat-msg-text">${msg.text}</div>
            <div class="chat-msg-time">${formatTime(msg.time)}</div>
          </div>
          ${isMe ? `<div class="chat-msg-avatar">${currentUser.avatar}</div>` : ""}
        </div>
      `;
    }).join("");

    // 滚动到底部
    container.scrollTop = container.scrollHeight;
  }

  // ========== 发送消息 ==========
  function sendMessage() {
    const input = $("#chatInput");
    if (!input || !currentChatUser) return;

    const text = input.value.trim();
    if (!text) return;

    const messages = getChatMessages(currentChatUser.id);
    messages.push({
      from: "me",
      text: text,
      time: Date.now()
    });
    saveChatMessages(currentChatUser.id, messages);

    input.value = "";
    renderChatMessages();

    // 模拟自动回复
    setTimeout(() => {
      const replies = [
        "哈哈，说得对！",
        "这个我也喜欢吃！",
        "下次一起做饭呀～",
        "你推荐的菜我试试",
        "好呀好呀！",
        "听起来很不错！"
      ];
      const reply = replies[Math.floor(Math.random() * replies.length)];
      const msgs = getChatMessages(currentChatUser.id);
      msgs.push({
        from: currentChatUser.id,
        text: reply,
        time: Date.now()
      });
      saveChatMessages(currentChatUser.id, msgs);
      renderChatMessages();
    }, 1000 + Math.random() * 1000);
  }

  // ========== 获取当前用户 ==========
  function getCurrentUser() {
    try {
      const data = localStorage.getItem("eat-ai-user");
      if (data) {
        const user = JSON.parse(data);
        return {
          name: user.nickname || user.name || "吃货",
          avatar: user.avatar || "🍅"
        };
      }
    } catch (e) {}
    return { name: "吃货", avatar: "🍅" };
  }

  // ========== 添加菜友弹层 ==========
  function showAddFriendModal() {
    const mask = $("#addFriendMask");
    if (!mask) return;
    mask.classList.remove("hidden");
    renderAddFriendResults("");
  }

  function hideAddFriendModal() {
    const mask = $("#addFriendMask");
    if (mask) mask.classList.add("hidden");
  }

  function renderAddFriendResults(keyword) {
    const results = $("#addFriendResults");
    if (!results) return;

    let users = MOCK_USERS.filter(u => !isFriend(u.id));
    if (keyword) {
      users = users.filter(u =>
        u.name.toLowerCase().includes(keyword.toLowerCase()) ||
        u.id.toLowerCase().includes(keyword.toLowerCase())
      );
    }

    if (users.length === 0) {
      results.innerHTML = '<div class="add-friend-empty">没有找到相关菜友</div>';
      return;
    }

    results.innerHTML = users.map(u => `
      <div class="add-friend-item" data-user-id="${u.id}">
        <div class="add-friend-avatar">${u.avatar}</div>
        <div class="add-friend-info">
          <div class="add-friend-name">${u.name}</div>
          <div class="add-friend-signature">${u.signature}</div>
        </div>
        <button class="add-friend-add-btn" data-add-id="${u.id}">添加</button>
      </div>
    `).join("");

    // 绑定添加按钮
    $$(".add-friend-add-btn").forEach(btn => {
      btn.addEventListener("click", (e) => {
        e.stopPropagation();
        const userId = btn.dataset.addId;
        const user = getUserById(userId);
        addFriend(userId);
        btn.textContent = "已添加";
        btn.disabled = true;
        btn.classList.add("added");
        if (user) alert("已添加" + user.name + "为菜友！");
        renderAddFriendResults($("#addFriendInput").value.trim());
      });
    });

    // 绑定点击用户查看资料
    $$(".add-friend-item").forEach(item => {
      item.addEventListener("click", () => {
        const userId = item.dataset.userId;
        hideAddFriendModal();
        showUserProfile(userId);
      });
    });
  }

  // ========== 初始化事件绑定 ==========
  function initEvents() {
    // 通讯录搜索
    const searchInput = $("#contactsSearchInput");
    if (searchInput) {
      searchInput.addEventListener("input", () => {
        renderContacts();
      });
    }

    // 添加菜友按钮
    const addBtn = $("#contactsAddBtn");
    if (addBtn) {
      addBtn.addEventListener("click", showAddFriendModal);
    }

    // 添加菜友弹层取消
    const cancelBtn = $("#addFriendCancel");
    if (cancelBtn) {
      cancelBtn.addEventListener("click", hideAddFriendModal);
    }

    // 点击遮罩关闭
    const mask = $("#addFriendMask");
    if (mask) {
      mask.addEventListener("click", (e) => {
        if (e.target === mask) hideAddFriendModal();
      });
    }

    // 添加菜友搜索
    const addInput = $("#addFriendInput");
    if (addInput) {
      addInput.addEventListener("input", () => {
        renderAddFriendResults(addInput.value.trim());
      });
    }

    // 聊天发送按钮
    const sendBtn = $("#chatSendBtn");
    if (sendBtn) {
      sendBtn.addEventListener("click", sendMessage);
    }

    // 聊天输入回车发送
    const chatInput = $("#chatInput");
    if (chatInput) {
      chatInput.addEventListener("keydown", (e) => {
        if (e.key === "Enter") sendMessage();
      });
    }
  }

  // ========== 暴露到全局 ==========
  window.renderContacts = renderContacts;
  window.showUserProfile = showUserProfile;
  window.startChat = startChat;
  window.socialInit = function () {
    initEvents();
  };

  // 页面加载完成后初始化
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", initEvents);
  } else {
    initEvents();
  }

})();


/* ===== utils\storage.js ===== */
/**
 * 今天吃啥 AI 版 · 本地存储工具
 * 
 * 统一管理 localStorage 操作，后续接入后端时可平滑替换。
 */

const Storage = {
  /** 读取数据 */
  get(key, defaultValue = null) {
    try {
      const value = localStorage.getItem(key);
      return value ? JSON.parse(value) : defaultValue;
    } catch (e) {
      console.warn(`[Storage] 读取失败: ${key}`, e);
      return defaultValue;
    }
  },

  /** 写入数据 */
  set(key, value) {
    try {
      localStorage.setItem(key, JSON.stringify(value));
      return true;
    } catch (e) {
      console.warn(`[Storage] 写入失败: ${key}`, e);
      return false;
    }
  },

  /** 删除数据 */
  remove(key) {
    try {
      localStorage.removeItem(key);
      return true;
    } catch (e) {
      console.warn(`[Storage] 删除失败: ${key}`, e);
      return false;
    }
  },

  /** 清空所有数据 */
  clear() {
    try {
      localStorage.clear();
      return true;
    } catch (e) {
      console.warn("[Storage] 清空失败", e);
      return false;
    }
  },

  /** 获取所有存储的键 */
  keys() {
    const keys = [];
    for (let i = 0; i < localStorage.length; i++) {
      keys.push(localStorage.key(i));
    }
    return keys;
  }
};

window.Storage = Storage;


/* ===== api\index.js ===== */
/**
 * 今天吃啥 AI 版 · 接口层
 * 
 * 【设计目的】
 * 统一管理所有数据获取接口，当前使用前端假数据，
 * 后续接入后端时只需修改此文件，无需改动业务逻辑。
 * 
 * 【接口规范】
 * - 统一返回格式：{ code: 0, message: "success", data: {} }
 * - 所有接口返回 Promise
 * - 错误码：0成功，40001参数错误，40101未登录，40301无权限，50000服务器错误
 * 
 * 【后端接入指引】
 * 1. 将 mock 数据替换为真实 API 请求（fetch/axios）
 * 2. 敏感操作（支付、删除、修改）必须走后端校验
 * 3. API Key 等密钥必须由后端代理，不能暴露在前端
 */

// ==================== 统一响应封装 ====================
function success(data, message = "success") {
  return Promise.resolve({ code: 0, message, data });
}

function fail(code, message) {
  return Promise.reject({ code, message, data: null });
}

// ==================== 用户相关接口 ====================
const UserAPI = {
  /** 微信登录（后端接入时使用） */
  login(code) {
    // TODO: 后端接入 - 调用 wx.login 获取 code，后端 code2session 换取 openid
    return success({ userId: "local_user", token: "local_token" });
  },

  /** 获取用户信息 */
  getUserInfo(userId) {
    // 当前从 localStorage 读取
    const userInfo = JSON.parse(localStorage.getItem("eat-ai-user") || "{}");
    return success(userInfo);
  },

  /** 更新用户信息 */
  updateUserInfo(userId, userInfo) {
    localStorage.setItem("eat-ai-user", JSON.stringify(userInfo));
    return success(userInfo);
  },

  /** 获取用户口味偏好 */
  getUserPrefs(userId) {
    const prefs = JSON.parse(localStorage.getItem("eat-ai-prefs") || "null");
    return success(prefs);
  },

  /** 更新用户口味偏好 */
  updateUserPrefs(userId, prefs) {
    localStorage.setItem("eat-ai-prefs", JSON.stringify(prefs));
    return success(prefs);
  }
};

// ==================== 菜谱相关接口 ====================
const RecipeAPI = {
  /** 获取菜谱列表（在家做） */
  getRecipeList(filters = {}) {
    // 当前从前端数据获取，后续走后端分页查询
    const allRecipes = [...(window.RECIPES || []), ...(window.RECIPES2 || []), ...(window.RECIPES3 || []), ...(window.RECIPES4 || [])];
    let list = allRecipes;
    
    // 简单过滤
    if (filters.category && filters.category !== "any") {
      list = list.filter(r => r.tags && r.tags.includes(filters.category));
    }
    
    return success({ list, total: list.length });
  },

  /** 获取菜谱详情 */
  getRecipeDetail(recipeId) {
    const allRecipes = [...(window.RECIPES || []), ...(window.RECIPES2 || []), ...(window.RECIPES3 || []), ...(window.RECIPES4 || [])];
    const recipe = allRecipes.find(r => r.id === recipeId || r.name === recipeId);
    if (!recipe) return fail(40401, "菜谱不存在");
    return success(recipe);
  },

  /** AI推算菜单 */
  generateMenu(params) {
    // 当前调用前端引擎，后续走后端 AI 接口
    // 注意：LLM API Key 必须由后端代理，不能在前端直接调用
    return success({ dishes: [], reason: "", nutrition: {} });
  }
};

// ==================== 外卖相关接口 ====================
const TakeoutAPI = {
  /** 获取外卖商家列表 */
  getTakeoutList(filters = {}) {
    const allShops = window.TAKEOUT_SHOPS || [];
    let list = allShops;
    
    if (filters.category && filters.category !== "any") {
      list = list.filter(s => s.category === filters.category);
    }
    
    return success({ list, total: list.length });
  },

  /** 获取商家详情 */
  getTakeoutDetail(shopId) {
    const allShops = window.TAKEOUT_SHOPS || [];
    const shop = allShops.find(s => s.id === shopId);
    if (!shop) return fail(40402, "商家不存在");
    return success(shop);
  }
};

// ==================== 餐厅相关接口 ====================
const RestaurantAPI = {
  /** 获取餐厅列表（出去吃） */
  getRestaurantList(filters = {}) {
    const allRestaurants = window.RESTAURANTS || [];
    let list = allRestaurants;
    
    if (filters.scene && filters.scene !== "any") {
      list = list.filter(r => r.tags && r.tags.includes(filters.scene));
    }
    
    return success({ list, total: list.length });
  },

  /** 获取餐厅详情 */
  getRestaurantDetail(restaurantId) {
    const allRestaurants = window.RESTAURANTS || [];
    const restaurant = allRestaurants.find(r => r.id === restaurantId);
    if (!restaurant) return fail(40403, "餐厅不存在");
    return success(restaurant);
  }
};

// ==================== 记录/历史接口 ====================
const RecordAPI = {
  /** 获取历史记录 */
  getHistory(userId, filters = {}) {
    const history = JSON.parse(localStorage.getItem("eat-ai-history") || "[]");
    let list = history;
    
    if (filters.type && filters.type !== "all") {
      list = list.filter(h => h.type === filters.type);
    }
    
    return success({ list, total: list.length });
  },

  /** 添加记录 */
  addRecord(userId, record) {
    const history = JSON.parse(localStorage.getItem("eat-ai-history") || "[]");
    record.id = Date.now();
    record.userId = userId;
    record.createdAt = new Date().toISOString();
    history.unshift(record);
    localStorage.setItem("eat-ai-history", JSON.stringify(history.slice(0, 100)));
    return success(record);
  },

  /** 删除记录（软删除） */
  deleteRecord(userId, recordId) {
    const history = JSON.parse(localStorage.getItem("eat-ai-history") || "[]");
    const idx = history.findIndex(h => h.id === recordId && h.userId === userId);
    if (idx >= 0) {
      history[idx].deleted = true;
      history[idx].deletedAt = new Date().toISOString();
      localStorage.setItem("eat-ai-history", JSON.stringify(history));
    }
    return success({ deleted: true });
  }
};

// ==================== 收藏接口 ====================
const FavoriteAPI = {
  /** 获取收藏列表 */
  getFavorites(userId, type = "all") {
    const favorites = JSON.parse(localStorage.getItem("eat-ai-favorites") || "[]");
    let list = favorites;
    if (type !== "all") {
      list = list.filter(f => f.type === type);
    }
    return success({ list, total: list.length });
  },

  /** 添加收藏 */
  addFavorite(userId, item) {
    const favorites = JSON.parse(localStorage.getItem("eat-ai-favorites") || "[]");
    item.id = Date.now();
    item.userId = userId;
    item.createdAt = new Date().toISOString();
    favorites.unshift(item);
    localStorage.setItem("eat-ai-favorites", JSON.stringify(favorites.slice(0, 100)));
    return success(item);
  },

  /** 取消收藏 */
  removeFavorite(userId, favoriteId) {
    let favorites = JSON.parse(localStorage.getItem("eat-ai-favorites") || "[]");
    favorites = favorites.filter(f => !(f.id === favoriteId && f.userId === userId));
    localStorage.setItem("eat-ai-favorites", JSON.stringify(favorites));
    return success({ removed: true });
  }
};

// ==================== 导出 ====================
window.API = {
  user: UserAPI,
  recipe: RecipeAPI,
  takeout: TakeoutAPI,
  restaurant: RestaurantAPI,
  record: RecordAPI,
  favorite: FavoriteAPI
};

