  "西葫芦": ["角瓜", "茭瓜", "小南瓜"],
  "黄瓜": ["青瓜"],
  "胡萝卜": ["红萝卜", "甘笋"],
  "生菜": ["叶生菜", "球生菜", "罗马生菜"],
