  "鸡肉": ["鸡腿", "鸡翅", "整鸡", "土鸡", "三黄鸡"],
  "鸭肉": ["鸭腿", "鸭胸", "整鸭"],
  "鱼": ["草鱼", "鲤鱼", "鲫鱼", "鲈鱼", "鳜鱼", "黄花鱼", "带鱼"],
